**Script**

```js
// tools/check-assets.mjs — Cocos Creator 3.8 project checker. READ ONLY.
// Run: node tools/check-assets.mjs
import fs from 'node:fs'
import path from 'node:path'

const ASSETS = path.resolve('assets')
const problems = []
const add = (kind, file, why) => problems.push({ kind, file, why })

/** Recursive walk, returns every file path. */
function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.name.startsWith('.')) continue
    const p = path.join(dir, e.name)
    if (e.isDirectory()) walk(p, out)
    else out.push(p)
  }
  return out
}

const rel = (p) => path.relative(process.cwd(), p).split(path.sep).join('/')
const files = walk(ASSETS)
const metas = new Set(files.filter((f) => f.endsWith('.meta')))
const uuids = new Map()

for (const f of files) {
  if (f.endsWith('.meta')) {
    // orphaned .meta: the source file is gone
    if (!fs.existsSync(f.slice(0, -5))) add('orphaned meta', rel(f), 'no source file next to it')
    try {
      const uuid = JSON.parse(fs.readFileSync(f, 'utf8')).uuid
      if (!uuid) add('broken meta', rel(f), 'no uuid field')
      else if (uuids.has(uuid)) add('duplicate uuid', rel(f), 'collides with ' + uuids.get(uuid))
      else uuids.set(uuid, rel(f))
    } catch { add('broken meta', rel(f), 'not valid JSON') }
    continue
  }

  // regular file: must have a .meta
  if (!metas.has(f + '.meta')) add('missing meta', rel(f), 'never imported by the Editor')

  // scripts/core/ must run outside the engine
  if (f.includes(path.join('scripts', 'core')) && f.endsWith('.ts')) {
    const src = fs.readFileSync(f, 'utf8')
    if (/from\s+['"]cc['"]/.test(src)) {
      add('core touches engine', rel(f), "imports from 'cc' — core must be testable under plain node")
    }
  }

  // large images outside a bundle tend to end up in the main package
  if (/\.(png|jpg|webp)$/i.test(f) && !f.includes(path.sep + 'bundles' + path.sep)) {
    const kb = fs.statSync(f).size / 1024
    if (kb > 512) add('heavy image', rel(f), Math.round(kb) + ' KB outside bundles/ — check the main package')
  }
}

if (!problems.length) {
  console.log('✓ assets/ is clean — ' + files.length + ' files, ' + uuids.size + ' uuids')
  process.exit(0)
}
const byKind = {}
for (const p of problems) (byKind[p.kind] ||= []).push(p)
for (const [kind, list] of Object.entries(byKind)) {
  console.error('\n✗ ' + kind + ' (' + list.length + ')')
  for (const p of list) console.error('  ' + p.file + ' — ' + p.why)
}
console.error('\nTotal: ' + problems.length + ' problems')
process.exit(1)
```

**Try it**
- Clean project: prints `✓ assets/ is clean — 412 files, 206 uuids`, exits 0.
- Delete a `.png` but keep its `.png.meta`: rerunning must report `✗ orphaned meta (1)` and exit 1.
- Add `import { Node } from 'cc'` to a file in `scripts/core/`: must report `✗ core touches engine (1)`.

nodes.body:
Mọi thứ trong Cocos là **Node**. Node có transform, có cha con, và mang **Component**. Không có hệ cây riêng cho UI như `RectTransform` bên Unity — một nút bấm cũng chỉ là node mang `UITransform` + `Sprite` + `Button`.

Node này là bộ xương: vòng đời chạy theo thứ tự nào, scene nạp ra sao, prefab sinh ra và chết đi thế nào. Sai ở đây thì mọi node khác trong nhánh đều lung lay.

## Vòng đời, theo đúng thứ tự

| Hàm | Khi chạy | Dùng để |
|---|---|---|
| `onLoad()` | Node được nạp vào scene, **trước** khi có gì hiển thị | Lấy tham chiếu, khởi tạo dữ liệu nội bộ |
| `onEnable()` | Mỗi lần node/component bật lên | Đăng ký listener |
| `start()` | Ngay **trước frame `update` đầu tiên** sau khi bật | Việc cần mọi node khác đã `onLoad` xong |
| `update(dt)` | Mỗi frame | Logic theo thời gian. `dt` tính bằng **giây** |
| `lateUpdate(dt)` | Sau mọi `update` trong frame | Camera bám theo, thứ phải chạy sau cùng |
| `onDisable()` | Mỗi lần tắt | **Gỡ listener** — không ai gỡ hộ |
| `onDestroy()` | Khi node bị huỷ | Trả tài nguyên, giải phóng tham chiếu |

Hai điều làm người từ Unity sang vấp ngay:

1. **`dt` là tham số, không có `Time.deltaTime` toàn cục.** Hàm nào cần dt thì phải được truyền xuống. Đây là lý do các lớp logic thuần nên nhận `dt` như tham số ngay từ đầu.
2. **`node.destroy()` không xoá ngay** mà dồn tới cuối frame. Ngay sau khi gọi, node vẫn còn trong `parent.children`. Đếm số enemy còn sống ngay sau `destroy()` sẽ ra số sai.

Thứ tự giữa các component **không đảm bảo** trừ khi bạn khai. Cần cái này chạy trước cái kia thì dùng `@executionOrder(-1)` (số nhỏ chạy trước) — nhưng dùng tiết kiệm: một dự án mà thứ tự đúng nhờ ba chục `@executionOrder` là một dự án khó gỡ.

## Boot scene: một chỗ vào duy nhất

Đừng để scene gameplay tự khởi tạo mọi thứ. Dựng một `boot.scene` gần như rỗng, chỉ có một node `GameRoot`:

