Demo bốn thứ: máy trạng thái cấp phát bao nhiêu, tuần tự so với `WhenAll`, `async void` nuốt lỗi thế nào, và huỷ bằng `CancellationToken` hoạt động ra sao. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
// Lưu ý: console KHÔNG có SynchronizationContext, nên .Result ở đây không treo.
// Chính vì vậy phần deadlock chỉ mô tả, không demo — nó chỉ tái hiện trên Unity/UI thread.
using System;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;

static class Program
{
    static async Task Main()
    {
        // 1) cấp phát của một async method có điểm cắt thật
        long b0 = GC.GetTotalAllocatedBytes(true);
        for (int i = 0; i < 1000; i++) await AlreadyDoneAsync(i);      // không cắt: xong ngay
        long noSuspend = GC.GetTotalAllocatedBytes(true) - b0;

        b0 = GC.GetTotalAllocatedBytes(true);
        for (int i = 0; i < 1000; i++) await SuspendsAsync(i);         // có cắt: Task + máy trạng thái
        long withSuspend = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine("1000 lần gọi async:");
        Console.WriteLine($"  xong ngay, không cắt : {noSuspend,8} B  ({noSuspend / 1000} B mỗi lần)");
        Console.WriteLine($"  có await thật sự     : {withSuspend,8} B  ({withSuspend / 1000} B mỗi lần)\n");

        // 2) tuần tự so với song song
        var sw = Stopwatch.StartNew();
        await FetchAsync("a"); await FetchAsync("b"); await FetchAsync("c");
        long seq = sw.ElapsedMilliseconds;

        sw.Restart();
        var ta = FetchAsync("a"); var tb = FetchAsync("b"); var tc = FetchAsync("c");
        await Task.WhenAll(ta, tb, tc);
        Console.WriteLine($"3 việc, mỗi việc 100ms:");
        Console.WriteLine($"  await lần lượt : {seq} ms");
        Console.WriteLine($"  WhenAll        : {sw.ElapsedMilliseconds} ms  <- khởi động trước, chờ sau\n");

        // 3) async void nuốt lỗi
        Console.WriteLine("3) async void:");
        try { FireAndForgetVoid(); }
        catch (Exception) { Console.WriteLine("   bắt được (sẽ KHÔNG xảy ra)"); }
        await Task.Delay(150);
        Console.WriteLine("   -> lỗi trong async void không tới được try/catch của người gọi");

        Console.WriteLine("   async Task thì bắt được:");
        try { await FireAndForgetTask(); }
        catch (InvalidOperationException e) { Console.WriteLine($"   bắt được: {e.Message}\n"); }

        // 4) huỷ hợp tác
        using var cts = new CancellationTokenSource();
        var work = LongWorkAsync(cts.Token);
        await Task.Delay(250);
        cts.Cancel();                                   // người chơi bấm huỷ / đổi scene
        try { await work; }
        catch (OperationCanceledException) { Console.WriteLine("4) đã huỷ — đây là luồng BÌNH THƯỜNG, không log như lỗi"); }
    }

    static async Task<int> AlreadyDoneAsync(int x) { await Task.CompletedTask; return x; }

    static async Task<int> SuspendsAsync(int x) { await Task.Yield(); return x; }

    static async Task<string> FetchAsync(string name)
    {
        await Task.Delay(100);                          // giả lập I/O
        return name;
    }

    static async void FireAndForgetVoid()
    {
        await Task.Delay(50);
        // Ném ở đây là ném thẳng lên SynchronizationContext: console sẽ báo unhandled,
        // Unity sẽ log đỏ rồi đi tiếp — trong cả hai trường hợp, người GỌI không bắt được.
        try { throw new InvalidOperationException("lỗi trong async void"); }
        catch (Exception e) { Console.WriteLine($"   phải tự bắt TRONG hàm: {e.Message}"); }
    }

    static async Task FireAndForgetTask()
    {
        await Task.Delay(50);
        throw new InvalidOperationException("lỗi trong async Task");
    }

    static async Task LongWorkAsync(CancellationToken token)
    {
        for (int i = 0; i < 20; i++)
        {
            token.ThrowIfCancellationRequested();       // huỷ là HỢP TÁC: phải tự kiểm
            await Task.Delay(50, token);
        }
    }
}
```

**Chạy thử**
- Phần 1: hàm không có điểm cắt thật cấp phát rất ít; hàm có `await Task.Yield()` tốn cỡ **100–200 byte mỗi lần gọi**. Đủ để thấy vì sao `async` không hợp cho thứ chạy mỗi frame, và vì sao `ValueTask` tồn tại.
- Phần 2: tuần tự ~**300ms**, `WhenAll` ~**100ms**. Cùng số việc, khác chỗ đặt `await`.
- Phần 3: dòng "bắt được" của người gọi **không** in ra — chứng minh `async void` không đưa lỗi về cho ai. Bản `async Task` thì bắt được bình thường.
- Phần 4: sau 250ms, `Cancel()` làm `await work` ném `OperationCanceledException`. Bắt riêng nó và **không** log như lỗi — đó là luồng bình thường khi người chơi đổi màn.

Demo đo bốn thứ hay bị đoán sai: `List.Contains` so với `HashSet.Contains`, khai capacity trước so với để nó tự lớn, `RemoveAt` so với swap-back, và `ContainsKey`+indexer so với `TryGetValue`. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
// Mọi con số in ra đều là so sánh tương đối trên cùng một máy, không phải chuẩn tuyệt đối.
using System;
using System.Collections.Generic;
using System.Diagnostics;

static class Program
{
    const int N = 20_000;       // số phần tử
    const int Probes = 50_000;  // số lần tra cứu

    static void Main()
    {
        var rng = new Random(1);
        var ids = new int[N];
        for (int i = 0; i < N; i++) ids[i] = i * 3;

        var list = new List<int>(ids);
        var set = new HashSet<int>(ids);
        var map = new Dictionary<int, int>(N);
        foreach (var id in ids) map[id] = id;

        // 1) tìm trong List (O(n)) so với HashSet (O(1))
        var sw = Stopwatch.StartNew();
        int hits = 0;
        for (int i = 0; i < Probes; i++) if (list.Contains(rng.Next(N * 3))) hits++;
        long listMs = sw.ElapsedMilliseconds;

        sw.Restart();
        hits = 0;
        for (int i = 0; i < Probes; i++) if (set.Contains(rng.Next(N * 3))) hits++;
        long setMs = sw.ElapsedMilliseconds;

        Console.WriteLine($"Contains {Probes} lần trên {N} phần tử:");
        Console.WriteLine($"  List<int>    : {listMs} ms");
        Console.WriteLine($"  HashSet<int> : {setMs} ms   <- cùng câu hỏi, khác cấu trúc\n");

        // 2) capacity: để tự lớn so với khai trước
        long before = GC.GetTotalAllocatedBytes(true);
        var grow = new List<int>();
        for (int i = 0; i < N; i++) grow.Add(i);
        long growBytes = GC.GetTotalAllocatedBytes(true) - before;

        before = GC.GetTotalAllocatedBytes(true);
        var pre = new List<int>(N);
        for (int i = 0; i < N; i++) pre.Add(i);
        long preBytes = GC.GetTotalAllocatedBytes(true) - before;

        Console.WriteLine($"Thêm {N} phần tử:");
        Console.WriteLine($"  List rỗng      : {growBytes / 1024} KB cấp phát (mảng cũ thành rác mỗi lần grow)");
        Console.WriteLine($"  List({N}) : {preBytes / 1024} KB — một lần duy nhất\n");

        // 3) RemoveAt giữa mảng so với swap-back
        Console.WriteLine($"Xoá ~50% phần tử khỏi List {N}:");
        Console.WriteLine($"  RemoveAt  : {TimeRemoveAt(ids)} ms  (mỗi lần xoá phải dồn mảng)");
        Console.WriteLine($"  swap-back : {TimeSwapBack(ids)} ms  (thứ tự bị đảo — chấp nhận được với enemy/đạn)\n");

        // 4) ContainsKey + indexer so với TryGetValue
        sw.Restart();
        long sum = 0;
        for (int i = 0; i < Probes; i++) { int k = ids[i % N]; if (map.ContainsKey(k)) sum += map[k]; }
        long twoLookups = sw.ElapsedMilliseconds;

        sw.Restart();
        sum = 0;
        for (int i = 0; i < Probes; i++) { int k = ids[i % N]; if (map.TryGetValue(k, out var v)) sum += v; }
        long oneLookup = sw.ElapsedMilliseconds;

        Console.WriteLine($"Dictionary {Probes} lần đọc:");
        Console.WriteLine($"  ContainsKey + indexer : {twoLookups} ms  (hai lần băm)");
        Console.WriteLine($"  TryGetValue           : {oneLookup} ms  (một lần)");
        Console.WriteLine($"(hits={hits}, sum={sum} — giữ để trình biên dịch không cắt vòng lặp)");
    }

    static long TimeRemoveAt(int[] src)
    {
        var l = new List<int>(src);
        var sw = Stopwatch.StartNew();
        for (int i = l.Count - 1; i >= 0; i--) if (l[i] % 2 == 0) l.RemoveAt(i);
        sw.Stop();
        return sw.ElapsedMilliseconds;
    }

    static long TimeSwapBack(int[] src)
    {
        var l = new List<int>(src);
        var sw = Stopwatch.StartNew();
        for (int i = l.Count - 1; i >= 0; i--)
            if (l[i] % 2 == 0) { l[i] = l[l.Count - 1]; l.RemoveAt(l.Count - 1); }
        sw.Stop();
        return sw.ElapsedMilliseconds;
    }
}
```

**Chạy thử**
- Phần 1: `HashSet` nhanh hơn `List` **hàng trăm lần** ở n = 20.000. Giảm `N` xuống 16 rồi chạy lại — khoảng cách gần như biến mất, và đó là bài học quan trọng hơn: **n nhỏ thì mảng thắng**.
- Phần 2: `List` rỗng cấp phát gấp khoảng **2 lần** so với khai trước, vì mọi mảng trung gian đều thành rác.
- Phần 3: swap-back nhanh hơn `RemoveAt` rõ rệt và khoảng cách giãn ra theo n, vì `RemoveAt` phải dồn phần đuôi sau mỗi lần xoá.
- Phần 4: `TryGetValue` nhanh hơn cỡ **1.5–2 lần** — cùng kết quả, một nửa số lần băm.

Demo chứng minh rò rỉ bằng số chứ không bằng lời: dùng `WeakReference` để xem object nghe có được GC thu dọn không, sau khi huỷ đăng ký đúng và sau khi "huỷ" bằng lambda. Kèm trường hợp một listener ném exception làm câm các listener sau. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
using System;

// Người phát: sống tới hết chương trình, giống một event static trong game
static class GameEvents
{
    public static event Action<int> ScoreChanged;
    public static void Raise(int v) => ScoreChanged?.Invoke(v);
    public static int ListenerCount => ScoreChanged?.GetInvocationList().Length ?? 0;

    // Bắn an toàn: gọi từng listener riêng, một cái hỏng không làm câm những cái sau.
    // GetInvocationList() chỉ gọi được TRONG lớp khai báo event — đó chính là điều `event` bảo vệ.
    public static void RaiseSafe(int v)
    {
        var list = ScoreChanged?.GetInvocationList();
        if (list == null) return;
        foreach (Action<int> h in list)
            try { h(v); } catch (Exception e) { Console.WriteLine($"   nuốt lỗi của một listener: {e.Message}"); }
    }
}

// Người nghe: giống một panel UI, giữ theo nó một mảng lớn để thấy rõ cái giá của rò rỉ
class ScorePanel
{
    readonly byte[] textureIsh = new byte[1_000_000];   // 1 MB "tài nguyên" treo theo panel
    public readonly string Name;
    Action<int> boundLambda;

    public ScorePanel(string name) { Name = name; }

    public void SubscribeWithMethod() => GameEvents.ScoreChanged += OnScore;
    public void UnsubscribeMethod() => GameEvents.ScoreChanged -= OnScore;

    public void SubscribeWithLambda() { boundLambda = v => OnScore(v); GameEvents.ScoreChanged += boundLambda; }
    public void FakeUnsubscribeLambda() => GameEvents.ScoreChanged -= v => OnScore(v);  // KHÔNG xoá gì
    public void RealUnsubscribeLambda() => GameEvents.ScoreChanged -= boundLambda;      // xoá đúng

    void OnScore(int v) { if (textureIsh.Length == 0) Console.WriteLine(v); }
}

static class Program
{
    static void Main()
    {
        Console.WriteLine("— 1) huỷ đăng ký ĐÚNG bằng method group —");
        Console.WriteLine($"   sống sót sau GC: {SurvivesGc(p => { p.SubscribeWithMethod(); p.UnsubscribeMethod(); })}");

        Console.WriteLine("— 2) 'huỷ' bằng một lambda khác —");
        Console.WriteLine($"   sống sót sau GC: {SurvivesGc(p => { p.SubscribeWithLambda(); p.FakeUnsubscribeLambda(); })}   <- RÒ RỈ");

        Console.WriteLine("— 3) huỷ đúng lambda đã lưu —");
        Console.WriteLine($"   sống sót sau GC: {SurvivesGc(p => { p.SubscribeWithLambda(); p.RealUnsubscribeLambda(); })}");

        Console.WriteLine($"\nListener còn treo trên event: {GameEvents.ListenerCount}");

        Console.WriteLine("\n— 4) một listener ném exception —");
        GameEvents.ScoreChanged += v => Console.WriteLine("   A chạy");
        GameEvents.ScoreChanged += v => throw new InvalidOperationException("B hỏng");
        GameEvents.ScoreChanged += v => Console.WriteLine("   C chạy  <- dòng này KHÔNG in ra");
        try { GameEvents.Raise(10); } catch (Exception e) { Console.WriteLine($"   bắt được: {e.Message}"); }

        Console.WriteLine("\n— 5) cách chặn: bắn qua RaiseSafe, gọi từng listener trong try/catch —");
        GameEvents.RaiseSafe(10);
    }

    // Tạo một panel, chạy kịch bản đăng ký/huỷ, rồi xem GC có thu dọn được không
    static bool SurvivesGc(Action<ScorePanel> scenario)
    {
        var weak = MakePanel(scenario);
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        return weak.IsAlive;
    }

    static WeakReference MakePanel(Action<ScorePanel> scenario)
    {
        var panel = new ScorePanel("HUD");
        scenario(panel);
        return new WeakReference(panel);      // không giữ tham chiếu mạnh nào nữa
    }
}
```

> `RaiseSafe` nằm **trong** `GameEvents` chứ không ở ngoài, vì `GetInvocationList()` chỉ truy cập được từ lớp khai báo event — đúng cái mà từ khoá `event` bảo vệ. Trong dự án thật, đó là chỗ duy nhất được phép bắn sự kiện.

**Chạy thử**
- Trường hợp 1 và 3 in `False`: panel được GC thu dọn, 1 MB kèm theo được trả lại.
- Trường hợp 2 in **`True`** — panel vẫn sống dù không còn ai tham chiếu tới nó, chỉ vì một lambda đăng ký không huỷ được. Đây là rò rỉ sự kiện, nhìn thấy bằng số.
- Dòng "Listener còn treo" in ra **1**: đúng một listener ma còn lại.
- Phần 4: `C chạy` **không** được in — listener ném exception chặn mọi listener đăng ký sau nó. Đây là lý do hàm bắn sự kiện trong dự án thật nên gọi từng listener trong `try/catch`.

Demo ba thứ đo được: giá thật của `throw` so với mẫu `Try…`, `throw ex` xoá stack trace thế nào, và **mô phỏng null giả của Unity** bằng một lớp nạp chồng `==` — cách duy nhất để thấy cơ chế đó chạy mà không cần mở Unity. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
using System;
using System.Diagnostics;

// Mô phỏng UnityEngine.Object: nạp chồng == để "đã destroy" được coi như null.
// Đây đúng là cơ chế Unity dùng, viết lại tối giản để chạy được ngoài Unity.
class FakeUnityObject
{
    public string Name = "Panel";
    public bool Destroyed;

    public static bool operator ==(FakeUnityObject a, FakeUnityObject b)
    {
        bool aNull = a is null || a.Destroyed;      // 'is null' ở ĐÂY là so sánh tham chiếu thật
        bool bNull = b is null || b.Destroyed;
        return aNull && bNull ? true : ReferenceEquals(a, b);
    }
    public static bool operator !=(FakeUnityObject a, FakeUnityObject b) => !(a == b);
    public static implicit operator bool(FakeUnityObject o) => !(o is null) && !o.Destroyed;

    public override bool Equals(object o) => ReferenceEquals(this, o);
    public override int GetHashCode() => base.GetHashCode();
    public string Describe() => $"tôi là {Name}, Destroyed={Destroyed}";
}

static class Program
{
    const int N = 20_000;

    static void Main()
    {
        // 1) throw so với TryParse
        var bad = "abc";
        var sw = Stopwatch.StartNew();
        int ok = 0;
        for (int i = 0; i < N; i++)
        {
            try { ok += int.Parse(bad); } catch (FormatException) { }
        }
        long throwMs = sw.ElapsedMilliseconds;

        sw.Restart();
        for (int i = 0; i < N; i++) if (int.TryParse(bad, out var v)) ok += v;
        long tryMs = sw.ElapsedMilliseconds;

        Console.WriteLine($"{N} lần xử lý chuỗi sai:");
        Console.WriteLine($"  Parse + catch : {throwMs,5} ms");
        Console.WriteLine($"  TryParse      : {tryMs,5} ms   <- không ném thì không tốn gì\n");

        // 2) throw; so với throw ex;
        Console.WriteLine("2) stack trace sau khi ném lại:");
        Console.WriteLine($"  throw;    -> {FirstFrame(() => RethrowCorrect())}");
        Console.WriteLine($"  throw ex; -> {FirstFrame(() => RethrowWrong())}   <- mất chỗ lỗi thật\n");

        // 3) null giả
        var panel = new FakeUnityObject();
        panel.Destroyed = true;                      // tương đương Destroy(gameObject)

        Console.WriteLine("3) object đã 'Destroy':");
        Console.WriteLine($"  panel == null   : {panel == null}    <- toán tử nạp chồng: ĐÚNG");
        Console.WriteLine($"  panel is null   : {panel is null}    <- so sánh tham chiếu: KHÔNG thấy");
        Console.WriteLine($"  if (!panel)     : {!panel}    <- ép sang bool: ĐÚNG");
        Console.WriteLine($"  panel?.Describe(): {panel?.Describe()}");
        Console.WriteLine("  ^ dòng trên VẪN chạy vào object đã chết — trong Unity đây là MissingReferenceException");
        var backup = new FakeUnityObject { Name = "Backup" };
        Console.WriteLine($"  (panel ?? backup).Name : {(panel ?? backup).Name}   <- nhận về Panel đã chết, không phải Backup");
    }

    static void RethrowCorrect()
    {
        try { Deep(); }
        catch (InvalidOperationException) { throw; }          // giữ stack gốc
    }

    static void RethrowWrong()
    {
        try { Deep(); }
        catch (InvalidOperationException ex) { throw ex; }     // đặt lại stack từ đây
    }

    static void Deep() => throw new InvalidOperationException("lỗi thật nằm ở Deep()");

    // Lấy dòng đầu của stack trace để thấy nó trỏ vào đâu
    static string FirstFrame(Action a)
    {
        try { a(); return "(không ném)"; }
        catch (Exception e)
        {
            var line = (e.StackTrace ?? "").Split('\n')[0].Trim();
            return line.Length > 70 ? line.Substring(0, 70) : line;
        }
    }
}
```

**Chạy thử**
- Phần 1: đường `Parse + catch` chậm hơn `TryParse` **hàng trăm lần** ở 20.000 lần lặp. Đó là lý do mẫu `Try…` tồn tại — không phải vì `try` đắt, mà vì `throw` đắt.
- Phần 2: dòng `throw;` in ra frame `Deep()` — chỗ lỗi thật. Dòng `throw ex;` in ra `RethrowWrong()` — chỗ ném lại. Đúng một dấu chấm phẩy khác nhau, và nó là khác biệt giữa tìm ra bug trong 5 phút hay trong hai ngày.
- Phần 3: `panel == null` ra `True` trong khi `panel is null` ra `False`, và `panel?.Describe()` **vẫn chạy** rồi in ra `Destroyed=True`. Đây chính là cơ chế null giả của Unity, thấy tận mắt: `?.` bỏ qua toán tử nạp chồng nên nó không biết object đã chết.

Demo ba điều: constraint interface bỏ boxing (đo bằng byte), static field trong lớp generic là riêng cho từng T, và một `Pool<T>` dùng được thật trong game. Chạy bằng `dotnet run`; `Pool<T>` copy thẳng vào dự án Unity được.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
using System;
using System.Collections.Generic;

interface IDamageable { void TakeDamage(int amount); int Hp { get; } }

struct Crate : IDamageable        // struct implement interface — chỗ boxing hay xảy ra
{
    public int Hp { get; private set; }
    public void TakeDamage(int amount) => Hp -= amount;
}

// ---- Pool<T>: dùng được thật, copy sang Unity chỉ cần đổi factory ----
public class Pool<T> where T : class
{
    readonly Stack<T> idle;
    readonly Func<T> factory;
    readonly Action<T> onGet, onRelease;
    public int CountIdle => idle.Count;
    public int CountAll { get; private set; }

    public Pool(Func<T> factory, int prewarm = 0, Action<T> onGet = null, Action<T> onRelease = null)
    {
        this.factory = factory ?? throw new ArgumentNullException(nameof(factory));
        this.onGet = onGet; this.onRelease = onRelease;
        idle = new Stack<T>(Math.Max(4, prewarm));
        for (int i = 0; i < prewarm; i++) { idle.Push(factory()); CountAll++; }
    }

    public T Get()
    {
        T item;
        if (idle.Count > 0) item = idle.Pop();
        else { item = factory(); CountAll++; }
        onGet?.Invoke(item);
        return item;
    }

    public void Release(T item)
    {
        if (item == null) return;
        onRelease?.Invoke(item);
        idle.Push(item);           // dự án thật: thêm kiểm tra trả về hai lần
    }
}

class Bullet { public float Speed; public bool Active; }

// ---- static field trong lớp generic ----
static class Counter<T> { public static int Count; }

static class Program
{
    const int N = 500_000;

    static void Main()
    {
        // 1) boxing hay không boxing
        long b0 = GC.GetTotalAllocatedBytes(true);
        for (int i = 0; i < N; i++) HitViaInterface(new Crate());
        long boxed = GC.GetTotalAllocatedBytes(true) - b0;

        b0 = GC.GetTotalAllocatedBytes(true);
        for (int i = 0; i < N; i++) HitGeneric(new Crate());
        long generic = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine($"{N} lần gọi với struct:");
        Console.WriteLine($"  tham số kiểu interface : {boxed / 1024,6} KB  <- mỗi lần một lần boxing");
        Console.WriteLine($"  generic + constraint   : {generic,6} B   <- constrained call\n");

        // 2) static field là RIÊNG cho từng kiểu đóng
        Counter<int>.Count++;
        Counter<int>.Count++;
        Counter<float>.Count++;
        Counter<Bullet>.Count++;
        Console.WriteLine($"Counter<int>    = {Counter<int>.Count}");
        Console.WriteLine($"Counter<float>  = {Counter<float>.Count}");
        Console.WriteLine($"Counter<Bullet> = {Counter<Bullet>.Count}   <- ba biến khác nhau\n");

        // 3) Pool<T>
        var pool = new Pool<Bullet>(
            factory: static () => new Bullet(),
            prewarm: 32,
            onGet: static b => b.Active = true,
            onRelease: static b => { b.Active = false; b.Speed = 0f; });

        var live = new List<Bullet>(64);
        b0 = GC.GetTotalAllocatedBytes(true);
        for (int frame = 0; frame < 1000; frame++)
        {
            for (int i = 0; i < 16; i++) { var b = pool.Get(); b.Speed = 10f; live.Add(b); }
            for (int i = live.Count - 1; i >= 0; i--) { pool.Release(live[i]); live.RemoveAt(i); }
        }
        long poolBytes = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine($"Pool: 16.000 lần lấy/trả -> tạo mới tổng cộng {pool.CountAll} object");
        Console.WriteLine($"      cấp phát trong 1000 frame: {poolBytes} B");
    }

    static void HitViaInterface(IDamageable target) => target.TakeDamage(1);          // boxing
    static void HitGeneric<T>(T target) where T : IDamageable => target.TakeDamage(1); // không
}
```

**Chạy thử**
- Phần 1: đường interface cấp phát cỡ **12 MB** cho 500.000 lần gọi (24 byte mỗi lần boxing); đường generic in ra **0 B**. Cùng một struct, cùng một hàm, khác nhau đúng ở constraint.
- Phần 2: ba bộ đếm ra `2`, `1`, `1` — bằng chứng rằng `Counter<int>` và `Counter<float>` là hai kiểu khác nhau với hai static field khác nhau.
- Phần 3: sau 1000 frame lấy/trả 16 viên đạn mỗi frame, tổng số object **được tạo** vẫn là 32 (số prewarm), và cấp phát trong vòng lặp là **0 B**. Đó là toàn bộ lý do object pool tồn tại.
- Thử đổi `Pool<T>` sang `where T : struct` rồi build IL2CPP với một T chỉ được tạo qua reflection — đó là lúc `ExecutionEngineException` xuất hiện.

Lời giải cho cả sáu bài live-coding, trong một file chạy được. Đây là code để **đọc rồi tự viết lại**, không phải để chép — trong phòng phỏng vấn không ai cho bạn dán.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
// Sáu lời giải live-coding. Mỗi lớp đều dùng được trong Unity (C# 9) nguyên vẹn.
using System;
using System.Collections.Generic;

// ============ BÀI 1: Pool<T> ============
public class Pool<T> where T : class
{
    readonly Stack<T> idle;
    readonly HashSet<T> busy;                       // chống trả về hai lần — thứ họ chờ bạn nghĩ tới
    readonly Func<T> create;
    readonly Action<T> onGet, onRelease;
    public int CountAll { get; private set; }
    public int CountIdle => idle.Count;

    public Pool(Func<T> create, int prewarm = 0, Action<T> onGet = null, Action<T> onRelease = null)
    {
        this.create = create ?? throw new ArgumentNullException(nameof(create));
        this.onGet = onGet; this.onRelease = onRelease;
        idle = new Stack<T>(Math.Max(4, prewarm));
        busy = new HashSet<T>();
        for (int i = 0; i < prewarm; i++) { idle.Push(create()); CountAll++; }
    }

    public T Get()
    {
        T item = idle.Count > 0 ? idle.Pop() : Grow();
        busy.Add(item);
        onGet?.Invoke(item);
        return item;
    }

    public bool Release(T item)
    {
        if (item == null) return false;
        if (!busy.Remove(item)) return false;       // trả hai lần, hoặc trả thứ không phải của pool
        onRelease?.Invoke(item);                     // RESET ở đây, nếu không sẽ mang trạng thái cũ
        idle.Push(item);
        return true;
    }

    T Grow() { CountAll++; return create(); }
}

// ============ BÀI 2: Event bus huỷ đăng ký an toàn ============
public class EventBus<TArg>
{
    readonly List<Action<TArg>> listeners = new List<Action<TArg>>();
    readonly List<Action<TArg>> scratch = new List<Action<TArg>>();   // bản sao để bắn, dùng lại

    public void Subscribe(Action<TArg> h) { if (h != null && !listeners.Contains(h)) listeners.Add(h); }
    public void Unsubscribe(Action<TArg> h) { listeners.Remove(h); }

    public void Raise(TArg arg)
    {
        scratch.Clear();
        scratch.AddRange(listeners);                 // bắn trên BẢN SAO: listener huỷ giữa chừng không vỡ
        for (int i = 0; i < scratch.Count; i++)
        {
            try { scratch[i](arg); }
            catch (Exception e) { Console.WriteLine($"   listener lỗi, bỏ qua: {e.Message}"); }
        }
    }
    public int Count => listeners.Count;
}

// ============ BÀI 3: shallow copy so với deep copy ============
public class Loadout
{
    public string Name;
    public List<string> Items = new List<string>();

    public Loadout Shallow() => (Loadout)MemberwiseClone();   // Items DÙNG CHUNG
    public Loadout Deep() => new Loadout { Name = Name, Items = new List<string>(Items) };
}

// ============ BÀI 4: LRU cache O(1) ============
public class LruCache<TKey, TValue>
{
    readonly int capacity;
    readonly Dictionary<TKey, LinkedListNode<(TKey key, TValue val)>> map;
    readonly LinkedList<(TKey key, TValue val)> order;   // đầu = mới dùng nhất

    public LruCache(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        this.capacity = capacity;
        map = new Dictionary<TKey, LinkedListNode<(TKey, TValue)>>(capacity);
        order = new LinkedList<(TKey, TValue)>();
    }

    public bool TryGet(TKey key, out TValue value)
    {
        if (!map.TryGetValue(key, out var node)) { value = default; return false; }
        order.Remove(node); order.AddFirst(node);     // O(1) vì đã cầm node
        value = node.Value.val;
        return true;
    }

    public void Put(TKey key, TValue value)
    {
        if (map.TryGetValue(key, out var node))
        {
            node.Value = (key, value);
            order.Remove(node); order.AddFirst(node);
            return;
        }
        if (map.Count >= capacity)
        {
            var last = order.Last;                     // phần tử lâu không dùng nhất
            order.RemoveLast();
            map.Remove(last.Value.key);
        }
        map[key] = order.AddFirst((key, value));
    }
    public int Count => map.Count;
}

// ============ BÀI 5: binary heap cho A* (Unity không có PriorityQueue) ============
public class MinHeap<T>
{
    readonly List<T> items;
    readonly Comparison<T> cmp;

    public MinHeap(Comparison<T> cmp, int capacity = 16)
    { this.cmp = cmp; items = new List<T>(capacity); }

    public int Count => items.Count;

    public void Push(T item)
    {
        items.Add(item);
        int i = items.Count - 1;
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (cmp(items[i], items[parent]) >= 0) break;
            (items[i], items[parent]) = (items[parent], items[i]);
            i = parent;
        }
    }

    public T Pop()
    {
        if (items.Count == 0) throw new InvalidOperationException("heap rỗng");
        T top = items[0];
        items[0] = items[items.Count - 1];
        items.RemoveAt(items.Count - 1);              // swap-back, O(1)
        int i = 0;
        while (true)
        {
            int l = i * 2 + 1, r = l + 1, best = i;
            if (l < items.Count && cmp(items[l], items[best]) < 0) best = l;
            if (r < items.Count && cmp(items[r], items[best]) < 0) best = r;
            if (best == i) break;
            (items[i], items[best]) = (items[best], items[i]);
            i = best;
        }
        return top;
    }
}

// ============ BÀI 6: xoá nhiều phần tử khi đang duyệt ============
public static class ListOps
{
    public static int RemoveAllSwapBack<T>(List<T> list, Predicate<T> match)
    {
        int removed = 0;
        for (int i = list.Count - 1; i >= 0; i--)
            if (match(list[i]))
            {
                list[i] = list[list.Count - 1];       // kéo phần tử cuối lấp vào
                list.RemoveAt(list.Count - 1);        // xoá ở cuối: O(1), không dồn mảng
                removed++;
            }
        return removed;
    }
}

class Bullet { public float Speed; public bool Active; public override string ToString() => $"B({Speed})"; }

static class Program
{
    static void Main()
    {
        // 1) Pool
        var pool = new Pool<Bullet>(static () => new Bullet(), prewarm: 2,
            onGet: static b => b.Active = true,
            onRelease: static b => { b.Active = false; b.Speed = 0f; });   // reset!
        var b1 = pool.Get(); b1.Speed = 9f;
        pool.Release(b1);
        var b2 = pool.Get();
        Console.WriteLine($"1) Pool: lấy lại cùng object = {ReferenceEquals(b1, b2)}, speed sau reset = {b2.Speed}");
        Console.WriteLine($"   trả về lần hai bị chặn: {pool.Release(b2)} rồi {pool.Release(b2)}");

        // 2) Event bus: listener tự huỷ đăng ký GIỮA LÚC đang bắn
        var bus = new EventBus<int>();
        Action<int> a = null, c = null;
        a = v => { Console.WriteLine($"2) A nhận {v}, tự huỷ đăng ký"); bus.Unsubscribe(a); };
        Action<int> bErr = v => throw new InvalidOperationException("B hỏng");
        c = v => Console.WriteLine($"   C vẫn nhận {v} dù A đã huỷ và B ném exception");
        bus.Subscribe(a); bus.Subscribe(bErr); bus.Subscribe(c);
        bus.Raise(7);
        Console.WriteLine($"   còn {bus.Count} listener\n");

        // 3) shallow vs deep
        var src = new Loadout { Name = "P1" }; src.Items.Add("sword");
        var sh = src.Shallow(); var dp = src.Deep();
        src.Items.Add("shield");
        Console.WriteLine($"3) gốc={src.Items.Count} shallow={sh.Items.Count} deep={dp.Items.Count}");
        Console.WriteLine($"   shallow dùng CHUNG list: {ReferenceEquals(src.Items, sh.Items)}\n");

        // 4) LRU
        var lru = new LruCache<int, string>(2);
        lru.Put(1, "a"); lru.Put(2, "b");
        lru.TryGet(1, out _);                          // 1 thành mới dùng nhất
        lru.Put(3, "c");                                // đẩy 2 ra, KHÔNG phải 1
        Console.WriteLine($"4) LRU(2): còn 1? {lru.TryGet(1, out _)} | còn 2? {lru.TryGet(2, out _)} | còn 3? {lru.TryGet(3, out _)}\n");

        // 5) MinHeap
        var heap = new MinHeap<(int node, float f)>(static (x, y) => x.f.CompareTo(y.f));
        foreach (var n in new[] { (1, 4.5f), (2, 1.2f), (3, 3.3f), (4, 0.7f) }) heap.Push(n);
        Console.Write("5) MinHeap lấy ra theo thứ tự f: ");
        while (heap.Count > 0) Console.Write($"{heap.Pop().node} ");
        Console.WriteLine("\n");

        // 6) xoá swap-back
        var bullets = new List<Bullet>();
        for (int i = 0; i < 10; i++) bullets.Add(new Bullet { Speed = i });
        int gone = ListOps.RemoveAllSwapBack(bullets, static b => b.Speed % 2 == 0);
        Console.WriteLine($"6) xoá {gone} viên, còn {bullets.Count}: {string.Join(" ", bullets)}");
        Console.WriteLine("   thứ tự bị đảo — đó là cái giá của swap-back, và với đạn thì không sao");
    }
}
```

**Chạy thử**
- Bài 1: `ReferenceEquals` ra `True` (đúng object được tái sử dụng) và `speed = 0` (đã reset). Lần `Release` thứ hai trả về `False` — chính là trường hợp biên người phỏng vấn hay hỏi.
- Bài 2: A huỷ đăng ký ngay trong lúc sự kiện đang bắn, B ném exception, mà C **vẫn nhận được** — vì `Raise` chạy trên bản sao và bọc từng listener trong `try/catch`. Bỏ `scratch` đi rồi chạy lại để thấy nó vỡ.
- Bài 3: `shallow` đếm 2 (dùng chung list với gốc), `deep` đếm 1. Một dòng in ra đủ để phân biệt hai khái niệm.
- Bài 4: sau `Put(3)`, khoá **2** bị đẩy ra chứ không phải 1 — vì 1 vừa được `TryGet` nên nó là mới dùng nhất.
- Bài 5: heap in ra `4 2 3 1` — đúng thứ tự `f` tăng dần, mỗi lần lấy là O(log n).
- Bài 6: còn 5 viên, thứ tự bị đảo. Nói được vì sao đảo, và vì sao trong trường hợp này không sao, là phần chấm điểm thật.

nodes.body:
LINQ là thứ đầu tiên người viết C# ngoài game khen và là thứ đầu tiên người tối ưu game xoá đi. Cả hai đều đúng, vì họ nói về hai chỗ khác nhau: LINQ trong editor tool, code load màn, test, backend — tuyệt vời. LINQ trong `Update` với 500 đối tượng — là lý do game khựng.

Biết ranh giới đó, và **giải thích được vì sao**, là một trong những câu hỏi mid-level hay gặp nhất khi phỏng vấn Unity. Đáp án "LINQ chậm" không đủ; phải nói được **nó cấp phát cái gì**.

## LINQ chạy lúc nào — deferred execution

```csharp
var query = enemies.Where(e => e.hp < 50);   // KHÔNG duyệt gì cả — chỉ dựng một iterator
enemies.Add(new Enemy { hp = 10 });          // thêm sau khi đã "viết" truy vấn
int n = query.Count();                       // TỚI ĐÂY mới duyệt — và thấy cả phần tử vừa thêm
```

Truy vấn là **công thức**, không phải kết quả. Nó chỉ chạy khi có người duyệt: `foreach`, `ToList()`, `Count()`, `First()`. Hai hệ quả thực tế:

- **Duyệt hai lần là chạy hai lần.** `if (query.Any()) foreach (var x in query)` duyệt nguồn hai lượt. Nguồn là một file đọc từ đĩa hay một truy vấn đắt thì đó là lỗi hiệu năng im lặng.
- **Nguồn đổi giữa chừng thì kết quả đổi theo**, hoặc ném exception nếu nguồn là collection vừa bị sửa.

Chốt bằng `ToList()`/`ToArray()` khi muốn "chụp" kết quả tại một thời điểm — nhưng nhớ rằng đó là một mảng mới.

## Một dòng LINQ cấp phát những gì

```csharp
float limit = attackRange;                                   // biến cục bộ
var targets = enemies.Where(e => e.dist < limit)             // ① closure ② iterator
                     .OrderBy(e => e.dist)                   // ③ comparer ④ buffer ⑤ mảng key
                     .Take(3)                                // ⑥ iterator
                     .ToArray();                             // ⑦ mảng kết quả
```

| # | Cấp phát gì | Ghi chú |
|---|---|---|
| ① | Object chứa biến bị bắt (**display class**) + một delegate | Chỉ xảy ra khi lambda **bắt biến**. Lambda không bắt gì thì compiler cache lại, 0 byte |
| ② ⑥ | Một iterator object cho mỗi mắt xích | `Where`+`Select` liền nhau được .NET gộp thành một, nhưng vẫn là một object |
| ③ ④ ⑤ | Comparer, buffer nội bộ, mảng khoá sắp xếp | `OrderBy` là mắt xích đắt nhất trong chuỗi |
| ⑦ | Mảng kết quả | Kích thước đúng bằng số phần tử lấy được |

Cỡ vài trăm byte cho **một lần gọi**. Trong `Update` ở 60fps đó là vài chục KB mỗi giây, tức một lần GC mỗi vài chục giây — đúng kiểu khựng đều đặn mô tả ở [[unity-csharp-memory]].

Chi tiết đáng nói trong phỏng vấn: **chi phí nằm ở việc bắt biến, không phải ở chữ lambda**. `e => e.hp < 50` không bắt gì nên delegate được cache một lần; `e => e.hp < limit` bắt `limit` nên mỗi lần chạy sinh một object mới. Từ C# 9 (Unity 6 có) bạn ép được điều đó thành lỗi biên dịch:

```csharp
var dead = enemies.Where(static e => e.hp <= 0);   // static lambda: cấm bắt biến, khỏi lo
```

## Năm truy vấn hay gặp và bản viết lại 0 byte

```csharp
// 1) Tìm phần tử đầu thoả điều kiện
var t = enemies.FirstOrDefault(e => e.dist < r);
// ->
Enemy t = null;
for (int i = 0; i < enemies.Count; i++) if (enemies[i].dist < r) { t = enemies[i]; break; }

// 2) Có cái nào không
if (enemies.Any(e => e.dist < r)) { }
// ->
bool found = false;
for (int i = 0; i < enemies.Count && !found; i++) found = enemies[i].dist < r;

// 3) Lấy nhỏ nhất / gần nhất
var nearest = enemies.OrderBy(e => e.dist).First();
// ->  không cần sắp xếp gì cả, chỉ cần một lượt duyệt
Enemy nearest2 = null; float best = float.MaxValue;
for (int i = 0; i < enemies.Count; i++)
    if (enemies[i].dist < best) { best = enemies[i].dist; nearest2 = enemies[i]; }

// 4) Lọc ra danh sách
var alive = enemies.Where(e => e.hp > 0).ToList();
// ->  buffer là FIELD, Clear() giữ capacity
aliveBuffer.Clear();
for (int i = 0; i < enemies.Count; i++) if (enemies[i].hp > 0) aliveBuffer.Add(enemies[i]);

// 5) Gom nhóm
var byType = enemies.GroupBy(e => e.type).ToDictionary(g => g.Key, g => g.ToList());
// ->  Dictionary<K, List<V>> dựng sẵn, mỗi List Clear() thay vì new
foreach (var kv in byTypeCache) kv.Value.Clear();
for (int i = 0; i < enemies.Count; i++) byTypeCache[enemies[i].type].Add(enemies[i]);
```

Số 3 đáng để ý nhất: `OrderBy(...).First()` là **O(n log n) để lấy một phần tử** trong khi một vòng duyệt là O(n). Đây là lỗi hiệu năng phổ biến nhất trong code gameplay viết bằng LINQ, và nó không liên quan gì tới cấp phát — nó sai về thuật toán.

## `Any()` hay `Count() > 0`

```csharp
if (list.Count > 0) { }            // O(1) — thuộc tính của List
if (enumerable.Any()) { }          // dừng ngay ở phần tử đầu
if (enumerable.Count() > 0) { }    // DUYỆT HẾT rồi mới so sánh  ← sai
```

`Count()` của LINQ có đường tắt khi nguồn là `ICollection<T>`, nhưng với một chuỗi `Where(...)` thì không có đường tắt nào — nó duyệt trọn nguồn. Với một truy vấn đắt hoặc một chuỗi vô hạn, `Count() > 0` là bug chứ không chỉ là chậm.

## `yield return` — iterator tự viết

```csharp
public IEnumerable<Vector2Int> Neighbors(Vector2Int c)
{
    yield return new Vector2Int(c.x + 1, c.y);
    yield return new Vector2Int(c.x - 1, c.y);
    yield return new Vector2Int(c.x, c.y + 1);
    yield return new Vector2Int(c.x, c.y - 1);
}
```

Trình biên dịch biến hàm này thành một **class máy trạng thái**; mỗi lần gọi là một object mới (~50–70 byte). Đổi lại nó lười: người gọi `break` sớm thì phần còn lại không bao giờ chạy.

Đáng dùng cho: sinh dữ liệu lớn mà chỉ lấy một phần, duyệt cây, và toàn bộ Coroutine của Unity (`IEnumerator` chính là cơ chế này). Không đáng dùng cho: hàm trả về đúng bốn phần tử gọi mỗi frame trong pathfinding — ở đó hãy ghi thẳng vào một buffer do người gọi truyền vào.

```csharp
public void GetNeighbors(Vector2Int c, List<Vector2Int> buffer)   // 0 byte, người gọi giữ buffer
{
    buffer.Clear();
    buffer.Add(new Vector2Int(c.x + 1, c.y));
    // …
}
```

Mẫu "người gọi truyền buffer" chính là cách Unity thiết kế `Physics.RaycastNonAlloc` và `GetComponents(List<T>)` — thấy API nào có overload nhận `List<T>` thì đó là lý do.

## Ranh giới dùng được

| Chỗ | LINQ? | Vì sao |
|---|---|---|
| Editor tool, script build | **Thoải mái** | Chạy một lần, không có người chơi nào đang chờ |
| Load màn, khởi tạo, đọc config | **Được** | Vài chục ms lúc loading không ai thấy |
| UI mở bảng, sắp bảng xếp hạng | **Được**, nếu không mở mỗi frame | Một lần bấm là một lần chạy |
| `Update`, `FixedUpdate`, vòng lặp AI | **Không** | Nhân với 60 lần mỗi giây |
| Trong Job / Burst | **Không dùng được** | Job chỉ nhận kiểu blittable, không delegate |
| Test tự động | **Thoải mái** | Đọc được quan trọng hơn nhanh |

Cách nói trong phỏng vấn: *"LINQ là công cụ của code chạy một lần; vòng lặp là công cụ của code chạy mỗi frame."*

## Bẫy còn lại

- **`foreach` trên biến kiểu `IEnumerable<T>`** boxing enumerator, kể cả khi nguồn là `List<T>`. Giữ kiểu cụ thể ở biến cục bộ.
- **Trả `IEnumerable<T>` từ API công khai** giấu mất chi phí: người gọi không biết mỗi lần duyệt là một lần chạy lại. Trả `List<T>` hoặc nhận buffer.
- **Truy vấn bắt `this`**: lambda dùng field của lớp thì nó bắt luôn `this`, giữ sống cả object — nguồn rò rỉ khi truy vấn được lưu vào field tĩnh.
- **`ToList()` trong vòng lặp** là mảng mới mỗi vòng; đây là cách nhanh nhất để biến một hàm O(n) thành O(n²) về cấp phát.
- **LINQ trong Coroutine** vẫn tính là mỗi frame nếu coroutine `yield return null` mỗi frame.

## Kiểm tra nhanh

- [ ] Không có `using System.Linq` nào trong file chạy mỗi frame (grep là đủ)
- [ ] Truy vấn nào duyệt hai lần đã được `ToList()` một lần
- [ ] Không có `OrderBy(...).First()` — đã đổi thành một vòng duyệt tìm min
- [ ] Lambda trong code nóng đều là `static` hoặc không bắt biến
- [ ] Hàm nóng trả dữ liệu qua buffer của người gọi, không `yield return`
- [ ] Đã đo GC Alloc trước/sau khi bỏ LINQ, không chỉ tin là nhanh hơn

nodes.code:
Demo ba thứ: chi phí thật của một chuỗi LINQ so với vòng lặp tương đương, bug duyệt hai lần của deferred execution, và khác biệt giữa lambda bắt biến với lambda `static`. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;

class Enemy { public int Hp; public float Dist; }

static class Program
{
    const int N = 2000;
    const int Frames = 600;          // giả lập 10 giây ở 60fps

    static readonly List<Enemy> Enemies = new List<Enemy>(N);
    static readonly List<Enemy> Buffer = new List<Enemy>(N);   // buffer dùng lại

    static void Main()
    {
        var rng = new Random(7);
        for (int i = 0; i < N; i++)
            Enemies.Add(new Enemy { Hp = rng.Next(0, 100), Dist = (float)rng.NextDouble() * 50f });

        // ---- 1) LINQ so với vòng lặp, đo cả thời gian lẫn byte ----
        long b0 = GC.GetTotalAllocatedBytes(true);
        var sw = Stopwatch.StartNew();
        int sink = 0;
        for (int f = 0; f < Frames; f++) sink += LinqWay(12f);
        sw.Stop();
        long linqBytes = GC.GetTotalAllocatedBytes(true) - b0;
        long linqMs = sw.ElapsedMilliseconds;

        b0 = GC.GetTotalAllocatedBytes(true);
        sw.Restart();
        for (int f = 0; f < Frames; f++) sink += LoopWay(12f);
        sw.Stop();
        long loopBytes = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine($"{Frames} frame, n={N}:");
        Console.WriteLine($"  LINQ    : {linqMs,4} ms | {linqBytes / 1024,6} KB | {linqBytes / Frames,5} B/frame");
        Console.WriteLine($"  vòng lặp: {sw.ElapsedMilliseconds,4} ms | {loopBytes / 1024,6} KB | {loopBytes / Frames,5} B/frame\n");

        // ---- 2) deferred execution: nguồn đổi thì kết quả đổi ----
        var pending = new List<int> { 1, 2, 3 };
        var query = pending.Where(x => x > 1);           // chưa chạy
        pending.Add(99);                                  // thêm SAU khi viết truy vấn
        Console.WriteLine($"deferred: query.Count() = {query.Count()}  (3, vì 99 cũng được tính)");
        var snapshot = pending.Where(x => x > 1).ToList();
        pending.Add(100);
        Console.WriteLine($"snapshot: đã ToList() nên vẫn = {snapshot.Count}\n");

        // ---- 3) lambda bắt biến so với static lambda ----
        b0 = GC.GetTotalAllocatedBytes(true);
        for (int f = 0; f < Frames; f++) sink += CountCapturing(50);
        long capturing = GC.GetTotalAllocatedBytes(true) - b0;

        b0 = GC.GetTotalAllocatedBytes(true);
        for (int f = 0; f < Frames; f++) sink += CountStatic();
        long noCapture = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine($"lambda BẮT biến   : {capturing,7} B tổng — display class mới mỗi lần gọi");
        Console.WriteLine($"lambda static     : {noCapture,7} B tổng — delegate được cache một lần");
        Console.WriteLine($"(sink={sink})");
    }

    // O(n log n) + nhiều object mỗi lần gọi
    static int LinqWay(float range)
    {
        var near = Enemies.Where(e => e.Dist < range && e.Hp > 0)
                          .OrderBy(e => e.Dist)
                          .Take(3)
                          .ToArray();
        return near.Length;
    }

    // O(n), 0 byte: buffer là field, chỉ giữ 3 phần tử gần nhất bằng chèn có thứ tự
    static int LoopWay(float range)
    {
        Buffer.Clear();
        for (int i = 0; i < Enemies.Count; i++)
        {
            var e = Enemies[i];
            if (e.Dist >= range || e.Hp <= 0) continue;
            int at = Buffer.Count;
            while (at > 0 && Buffer[at - 1].Dist > e.Dist) at--;
            if (at >= 3) continue;
            Buffer.Insert(at, e);
            if (Buffer.Count > 3) Buffer.RemoveAt(Buffer.Count - 1);
        }
        return Buffer.Count;
    }

    static int CountCapturing(int limit)
    {
        int c = 0;
        Func<Enemy, bool> p = e => e.Hp > limit;        // bắt 'limit' -> object mới mỗi lần
        for (int i = 0; i < Enemies.Count; i++) if (p(Enemies[i])) c++;
        return c;
    }

    static int CountStatic()
    {
        int c = 0;
        Func<Enemy, bool> p = static e => e.Hp > 50;    // không bắt gì -> compiler cache
        for (int i = 0; i < Enemies.Count; i++) if (p(Enemies[i])) c++;
        return c;
    }
}
```

**Chạy thử**
- Phần 1: LINQ cấp phát cỡ **vài trăm byte mỗi frame** trong khi vòng lặp in ra **0 B/frame**. Thời gian cũng chênh vài lần, phần lớn do `OrderBy` sắp toàn bộ danh sách chỉ để lấy 3 phần tử.
- Phần 2: `query.Count()` ra **3** dù lúc viết truy vấn danh sách chỉ có 2 phần tử thoả — bằng chứng trực quan cho deferred execution. Bản `ToList()` thì đứng yên.
- Phần 3: lambda bắt biến cấp phát tổng vài chục KB, lambda `static` in ra **0 B**. Đây là chỗ thấy rõ "chi phí nằm ở việc bắt biến, không nằm ở chữ lambda".

Demo đo bốn thứ bằng byte: nối chuỗi so với `StringBuilder`, `Substring` so với `Span`, `new byte[]` so với `ArrayPool`, và `Dispose` so với finalizer. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
using System;
using System.Buffers;
using System.Diagnostics;
using System.Text;

sealed class WithDispose : IDisposable
{
    public static int Closed;
    bool disposed;
    public void Dispose() { if (disposed) return; disposed = true; Closed++; }
}

sealed class WithFinalizer
{
    public static int Finalized;
    ~WithFinalizer() { Finalized++; }          // chạy lúc nào thì GC quyết, không phải bạn
}

static class Program
{
    static void Main()
    {
        const int N = 5000;

        // 1) nối chuỗi so với StringBuilder
        long b0 = GC.GetTotalAllocatedBytes(true);
        var sw = Stopwatch.StartNew();
        string s = "";
        for (int i = 0; i < N; i++) s += i.ToString() + ",";
        long concatBytes = GC.GetTotalAllocatedBytes(true) - b0;
        long concatMs = sw.ElapsedMilliseconds;

        b0 = GC.GetTotalAllocatedBytes(true);
        sw.Restart();
        var sb = new StringBuilder(N * 5);
        for (int i = 0; i < N; i++) sb.Append(i).Append(',');
        string s2 = sb.ToString();
        long sbBytes = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine($"Nối {N} mẩu chuỗi:");
        Console.WriteLine($"  s += ...       : {concatBytes / 1024,7} KB | {concatMs} ms   <- O(n²)");
        Console.WriteLine($"  StringBuilder  : {sbBytes / 1024,7} KB | {sw.ElapsedMilliseconds} ms");
        Console.WriteLine($"  (cùng kết quả: {s.Length == s2.Length})\n");

        // 2) Substring so với ReadOnlySpan<char>
        string csv = string.Join(',', new int[2000]);
        b0 = GC.GetTotalAllocatedBytes(true);
        long sum = 0;
        for (int i = 0; i + 5 < csv.Length; i += 6) sum += csv.Substring(i, 5).Length;
        long subBytes = GC.GetTotalAllocatedBytes(true) - b0;

        b0 = GC.GetTotalAllocatedBytes(true);
        ReadOnlySpan<char> span = csv.AsSpan();
        for (int i = 0; i + 5 < span.Length; i += 6) sum += span.Slice(i, 5).Length;
        long spanBytes = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine($"Cắt chuỗi ~333 lần:");
        Console.WriteLine($"  Substring : {subBytes,7} B");
        Console.WriteLine($"  Span      : {spanBytes,7} B   <- không cấp phát, chỉ là cửa sổ nhìn vào\n");

        // 3) new byte[] so với ArrayPool
        b0 = GC.GetTotalAllocatedBytes(true);
        for (int i = 0; i < 2000; i++) { var tmp = new byte[4096]; tmp[0] = 1; }
        long newBytes = GC.GetTotalAllocatedBytes(true) - b0;

        var pool = ArrayPool<byte>.Shared;
        b0 = GC.GetTotalAllocatedBytes(true);
        for (int i = 0; i < 2000; i++)
        {
            byte[] rented = pool.Rent(4096);
            try { rented[0] = 1; }
            finally { pool.Return(rented); }       // quên dòng này là pool vô nghĩa
        }
        long poolBytes = GC.GetTotalAllocatedBytes(true) - b0;

        Console.WriteLine($"2000 buffer 4 KB:");
        Console.WriteLine($"  new byte[4096] : {newBytes / 1024,7} KB");
        Console.WriteLine($"  ArrayPool      : {poolBytes / 1024,7} KB\n");

        // 4) Dispose so với finalizer
        for (int i = 0; i < 1000; i++) { using var d = new WithDispose(); }
        for (int i = 0; i < 1000; i++) { var f = new WithFinalizer(); }

        Console.WriteLine($"Dispose đã chạy : {WithDispose.Closed}/1000  <- ngay lập tức, xác định");
        Console.WriteLine($"Finalizer đã chạy: {WithFinalizer.Finalized}/1000  <- chưa chắc cái nào");
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        Console.WriteLine($"Finalizer sau 2 lần GC ép buộc: {WithFinalizer.Finalized}/1000");
        Console.WriteLine($"(sum={sum})");
    }
}
```

**Chạy thử**
- Phần 1: nối chuỗi cấp phát **hàng chục MB** cho 5000 mẩu, `StringBuilder` cỡ **vài chục KB**. Chênh lệch ba chữ số, và nó lớn theo bình phương số vòng lặp.
- Phần 2: `Substring` cấp phát vài chục KB, `Span` in ra **0 B**.
- Phần 3: `ArrayPool` gần bằng 0 sau vài vòng đầu, vì mảng được mượn lại. Xoá dòng `pool.Return` rồi chạy lại — con số nhảy lên bằng đường `new`, đó là cách thấy tận mắt vì sao quên `Return` là hỏng.
- Phần 4: `Dispose` chạy **1000/1000 ngay lập tức**; finalizer thường in ra **0** trước khi ép GC, và kể cả sau hai lần `GC.Collect()` cũng không đảm bảo đủ 1000. Đó là toàn bộ lý do đừng trông vào finalizer để đóng tài nguyên.

Một file duy nhất gom mọi tính năng C# 8–9 **dùng được trong Unity 6**, mỗi tính năng kèm một ví dụ game thật. Chạy bằng `dotnet run`; mọi dòng trong đây đều biên dịch được trên Unity 6, trừ những dòng ghi rõ là phản ví dụ.

**Script**

```csharp
// Program.cs — mọi tính năng dưới đây đều hợp lệ với C# 9 (Unity 6).
using System;
using System.Collections.Generic;
using System.Linq;

enum DamageType { Physical, Fire, Piercing }
enum ArmorType { None, Wood, Metal }
enum GameState { Menu, Playing, Paused, GameOver }

// record: so sánh theo giá trị, có sẵn ToString đẹp, có 'with'
record SpawnConfig(string PrefabId, int Count, float Interval);

// readonly struct + IEquatable: kiểu giá trị dùng ở code nóng
readonly struct GridPos : IEquatable<GridPos>
{
    public readonly int X, Y;
    public GridPos(int x, int y) { X = x; Y = y; }
    public bool Equals(GridPos o) => X == o.X && Y == o.Y;
    public override bool Equals(object o) => o is GridPos p && Equals(p);
    public override int GetHashCode() => X * 397 ^ Y;
    public override string ToString() => $"({X},{Y})";
}

class Enemy
{
    public int Hp { get; init; }               // init: chỉ gán lúc khởi tạo (cần shim trên vài bản Unity)
    public DamageType Weakness { get; init; }
    public GridPos Cell { get; init; }
}

static class Program
{
    static void Main()
    {
        // 1) switch expression + tuple pattern = bảng tương khắc
        Console.WriteLine("1) bảng tương khắc:");
        foreach (var (dmg, armor) in new[]
                 { (DamageType.Fire, ArmorType.Wood), (DamageType.Fire, ArmorType.Metal),
                   (DamageType.Piercing, ArmorType.Metal), (DamageType.Physical, ArmorType.None) })
            Console.WriteLine($"   {dmg,-8} vs {armor,-5} = ×{Multiplier(dmg, armor)}");

        // 2) pattern matching: and / or / not / property pattern
        var enemies = new List<Enemy>
        {
            new Enemy { Hp = 80, Weakness = DamageType.Fire,     Cell = new GridPos(1, 1) },
            new Enemy { Hp = 15, Weakness = DamageType.Piercing, Cell = new GridPos(2, 3) },
            new Enemy { Hp = 0,  Weakness = DamageType.Physical, Cell = new GridPos(0, 0) },
        };

        Console.WriteLine("\n2) phân loại bằng pattern:");
        foreach (var e in enemies) Console.WriteLine($"   {e.Cell} hp={e.Hp,3} -> {Classify(e)}");

        // 3) record: so sánh giá trị + with
        var baseCfg = new SpawnConfig("goblin", 3, 1.5f);
        var sameCfg = new SpawnConfig("goblin", 3, 1.5f);
        var faster = baseCfg with { Interval = 0.5f };
        Console.WriteLine($"\n3) record:");
        Console.WriteLine($"   baseCfg == sameCfg : {baseCfg == sameCfg}   <- so sánh theo GIÁ TRỊ");
        Console.WriteLine($"   ReferenceEquals    : {ReferenceEquals(baseCfg, sameCfg)}   <- vẫn là hai object");
        Console.WriteLine($"   faster             : {faster}");

        // 4) tuple trả nhiều giá trị — ValueTuple là struct, không cấp phát
        var (hit, dist) = Probe(12f);
        Console.WriteLine($"\n4) tuple: hit={hit}, dist={dist}");

        // 5) static local function: cấm bắt biến -> không cấp phát closure
        Console.WriteLine($"5) tổng hp còn sống: {SumAlive(enemies)}");

        // 6) using declaration + ??= + Index/Range
        string log = "2026-09-13 ERROR mất kết nối";
        Console.WriteLine($"6) ngày: {log.AsSpan()[..10].ToString()} | mức: {log.Split(' ')[1]}");

        // 7) switch expression trên state — thiếu nhánh _ là ném lúc CHẠY, không phải lúc biên dịch
        foreach (GameState s in Enum.GetValues(typeof(GameState)))
            Console.WriteLine($"   {s} -> {Label(s)}");
    }

    static float Multiplier(DamageType t, ArmorType a) => (t, a) switch
    {
        (DamageType.Fire, ArmorType.Wood) => 2.0f,
        (DamageType.Fire, ArmorType.Metal) => 0.5f,
        (DamageType.Piercing, ArmorType.Metal) => 1.5f,
        _ => 1.0f,
    };

    static string Classify(Enemy e) => e switch
    {
        { Hp: <= 0 } => "đã chết",
        { Hp: < 20, Weakness: DamageType.Fire or DamageType.Piercing } => "sắp chết, có điểm yếu",
        { Hp: < 20 } => "sắp chết",
        not null => "khoẻ",
        _ => "không rõ",
    };

    static string Label(GameState s) => s switch
    {
        GameState.Menu => "Menu",
        GameState.Playing => "Đang chơi",
        GameState.Paused => "Tạm dừng",
        _ => "Kết thúc",                  // luôn có nhánh này, nếu không sẽ ném lúc chạy
    };

    static (bool hit, float dist) Probe(float range)
    {
        float d = range * 0.5f;
        return (d < range, d);            // ValueTuple: struct, 0 byte trên heap
    }

    static int SumAlive(List<Enemy> list)
    {
        // static local function: trình biên dịch CẤM nó bắt biến ngoài -> không tạo closure
        static bool Alive(Enemy e) => e.Hp > 0;

        int sum = 0;
        for (int i = 0; i < list.Count; i++) if (Alive(list[i])) sum += list[i].Hp;
        return sum;
    }
}
```

**Chạy thử**
- Phần 1 in ra bảng tương khắc; đọc code sẽ thấy nó gần như chính là cái bảng — đó là lý do tuple pattern đáng dùng cho dữ liệu cân bằng.
- Phần 3: `baseCfg == sameCfg` ra **`True`** trong khi `ReferenceEquals` ra `False` — hai object khác nhau nhưng bằng nhau về giá trị. Đổi `record` thành `class` rồi chạy lại: `==` thành `False`, và đó chính là cái bạn mất khi "hạ cấp" record thành class mà quên viết `Equals`.
- Phần 7: thử xoá nhánh `_` trong `Label` rồi chạy — biên dịch vẫn qua (chỉ cảnh báo), nhưng gặp `GameState.GameOver` là ném `SwitchExpressionException` lúc chạy.
- Dán cả file này vào Unity 6 (bỏ `Main`, gói vào một MonoBehaviour): mọi dòng đều biên dịch. Nếu `init` báo lỗi `IsExternalInit` thì thêm file shim năm dòng.

Demo in ra khác biệt giữa `override` và `new` — thứ đọc mô tả thì gật gù nhưng nhìn output mới nhớ — cộng một ví dụ composition nhỏ cho thấy tổ hợp hành vi không cần class mới. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
using System;
using System.Collections.Generic;

// ---------- phần 1: override vs new ----------
class Weapon
{
    public virtual string Fire() => "Weapon.Fire";
    public string Reload() => "Weapon.Reload";
    public Weapon() { Console.WriteLine("  ctor cha gọi: " + Fire()); }  // BẪY: gọi hàm ảo trong ctor
}

class Shotgun : Weapon
{
    readonly string ammoName = "shell";                 // gán SAU khi ctor cha chạy xong
    public override string Fire() => "Shotgun.Fire (" + (ammoName ?? "CHƯA GÁN") + ")";
    public new string Reload() => "Shotgun.Reload";
}

// ---------- phần 2: composition ----------
interface IAbility { string Name { get; } void Tick(Actor self, float dt); }

class Actor
{
    public string Name;
    public int Hp = 100;                                 // MỘT chủ sở hữu duy nhất của máu
    readonly List<IAbility> abilities = new List<IAbility>();
    public Actor With(IAbility a) { abilities.Add(a); return this; }
    public void Tick(float dt) { foreach (var a in abilities) a.Tick(this, dt); }
    public override string ToString() => $"{Name} hp={Hp}";
}

class Regen : IAbility
{
    public string Name => "Regen";
    public void Tick(Actor self, float dt) { self.Hp = Math.Min(100, self.Hp + (int)(5 * dt)); }
}

class Burning : IAbility
{
    public string Name => "Burning";
    public void Tick(Actor self, float dt) { self.Hp -= (int)(12 * dt); }
}

class Fly : IAbility
{
    public string Name => "Fly";
    public void Tick(Actor self, float dt) { /* chỉ đổi cách di chuyển, không đụng máu */ }
}

static class Program
{
    static void Main()
    {
        Console.WriteLine("— phần 1: override vs new —");
        Shotgun s = new Shotgun();
        Weapon w = s;                                    // CÙNG một object, hai kiểu khai báo

        Console.WriteLine($"w.Fire()   = {w.Fire()}");   // override -> theo kiểu THẬT
        Console.WriteLine($"s.Fire()   = {s.Fire()}");
        Console.WriteLine($"w.Reload() = {w.Reload()}"); // new -> theo kiểu KHAI BÁO
        Console.WriteLine($"s.Reload() = {s.Reload()}");

        Console.WriteLine("\n— phần 2: composition —");
        var bat = new Actor { Name = "Bat" }.With(new Fly()).With(new Regen());
        var burningBat = new Actor { Name = "BurningBat" }.With(new Fly()).With(new Burning());
        // tổ hợp thứ ba: KHÔNG cần class mới
        var burningRegenBat = new Actor { Name = "Phoenix" }.With(new Fly()).With(new Burning()).With(new Regen());

        for (int frame = 0; frame < 3; frame++)
            foreach (var a in new[] { bat, burningBat, burningRegenBat }) a.Tick(1f);

        Console.WriteLine(bat);
        Console.WriteLine(burningBat);
        Console.WriteLine(burningRegenBat);
    }
}
```

**Chạy thử**
- Dòng đầu in ra `Shotgun.Fire (CHƯA GÁN)`: constructor của lớp cha gọi hàm ảo **trước khi** field `ammoName` của lớp con được gán. Đây là lý do đừng gọi hàm ảo trong constructor — trong Unity thì đừng khởi tạo trong constructor, dùng `Awake`.
- `w.Fire()` và `s.Fire()` cho **cùng** kết quả (override), nhưng `w.Reload()` ra `Weapon.Reload` còn `s.Reload()` ra `Shotgun.Reload` — cùng một object, hai kết quả, chỉ vì kiểu khai báo khác nhau. Đó là `new`.
- Phần 2: `Phoenix` tổ hợp ba hành vi mà không có class nào tên `FlyingBurningRegenActor`. Đổi thứ tự `.With(...)` rồi chạy lại — máu cuối khác đi, và đó chính là cái giá của composition: **thứ tự chạy trở thành thứ bạn phải tự định nghĩa**.

Demo cho thấy race condition bằng số (kết quả sai và khác nhau mỗi lần chạy), so `lock` với `Interlocked`, rồi dựng mẫu producer–consumer với hàng đợi rút có giới hạn — đúng mẫu dùng trong Unity. Chạy bằng `dotnet run`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;

static class Program
{
    const int Threads = 4;
    const int PerThread = 250_000;

    static int unsafeCounter;
    static int lockedCounter;
    static int interlockedCounter;
    static readonly object gate = new object();      // private readonly: đúng cách

    static void Main()
    {
        Console.WriteLine($"{Threads} thread × {PerThread} lần tăng = kỳ vọng {Threads * PerThread}\n");

        // 1) không đồng bộ: sai, và sai khác nhau mỗi lần
        var sw = Stopwatch.StartNew();
        RunParallel(() => unsafeCounter++);
        Console.WriteLine($"  không khoá  : {unsafeCounter,9}  ({sw.ElapsedMilliseconds,3} ms)  <- MẤT dữ liệu");

        // 2) lock
        sw.Restart();
        RunParallel(() => { lock (gate) lockedCounter++; });
        Console.WriteLine($"  lock        : {lockedCounter,9}  ({sw.ElapsedMilliseconds,3} ms)");

        // 3) Interlocked
        sw.Restart();
        RunParallel(() => Interlocked.Increment(ref interlockedCounter));
        Console.WriteLine($"  Interlocked : {interlockedCounter,9}  ({sw.ElapsedMilliseconds,3} ms)  <- đúng và rẻ hơn\n");

        // 4) producer–consumer: nền tính, "main thread" áp dụng
        ProducerConsumerDemo();
    }

    static void RunParallel(Action body)
    {
        var tasks = new Task[Threads];
        for (int t = 0; t < Threads; t++)
            tasks[t] = Task.Run(() => { for (int i = 0; i < PerThread; i++) body(); });
        Task.WaitAll(tasks);
    }

    // Mẫu dùng trong Unity: thread nền chỉ sinh DỮ LIỆU, main thread áp dụng vào engine.
    static void ProducerConsumerDemo()
    {
        var results = new ConcurrentQueue<PathResult>();
        var done = 0;
        const int Jobs = 200;
        const int MaxApplyPerFrame = 8;               // trần để không tụt frame

        for (int j = 0; j < Jobs; j++)
        {
            int id = j;
            Task.Run(() =>
            {
                try
                {
                    var path = SolvePath(id);          // toán thuần, KHÔNG chạm engine
                    results.Enqueue(new PathResult { Id = id, Length = path });
                }
                catch (Exception e)
                {
                    // thread nền nuốt exception = "kết quả không bao giờ về"
                    results.Enqueue(new PathResult { Id = id, Length = -1, Error = e.Message });
                }
                finally { Interlocked.Increment(ref done); }
            });
        }

        int frame = 0, applied = 0, maxInOneFrame = 0;
        while (applied < Jobs)
        {
            frame++;
            int thisFrame = 0;
            while (thisFrame < MaxApplyPerFrame && results.TryDequeue(out var r))
            {
                // ĐÂY là chỗ duy nhất được Instantiate / gán transform trong Unity
                applied++; thisFrame++;
                if (r.Length < 0) Console.WriteLine($"   job {r.Id} lỗi: {r.Error}");
            }
            maxInOneFrame = Math.Max(maxInOneFrame, thisFrame);
            Thread.Sleep(1);                           // giả lập một frame
        }

        Console.WriteLine($"4) producer–consumer: {Jobs} job xong sau {frame} 'frame'");
        Console.WriteLine($"   nhiều nhất {maxInOneFrame} kết quả được áp dụng trong một frame (trần {MaxApplyPerFrame})");
        Console.WriteLine($"   thread nền đã chạy xong: {Volatile.Read(ref done)}/{Jobs}");
    }

    struct PathResult { public int Id; public int Length; public string Error; }

    static int SolvePath(int seed)
    {
        var rng = new Random(seed);                    // MỖI thread một Random riêng
        int acc = 0;
        for (int i = 0; i < 20_000; i++) acc += rng.Next(0, 3);
        return acc;
    }
}
```

**Chạy thử**
- Dòng "không khoá" in ra một số **nhỏ hơn 1.000.000** và **đổi mỗi lần chạy** — đó là race condition, nhìn thấy bằng số chứ không bằng lý thuyết.
- `lock` và `Interlocked` đều ra đúng 1.000.000; `Interlocked` thường nhanh hơn `lock` vài lần cho phép tăng một biến.
- Phần 4: số kết quả áp dụng trong một "frame" không bao giờ vượt trần 8, dù hàng đợi có lúc dồn hàng chục phần tử. Bỏ trần đi rồi chạy lại để thấy một frame nuốt cả trăm kết quả — đúng kiểu khựng mà tách thread lẽ ra phải tránh.
- Thử đổi `ConcurrentQueue` thành `Queue` thường: kết quả sẽ sai hoặc ném exception ngẫu nhiên, và không phải lần chạy nào cũng lộ ra.

Demo đo ba thứ trong một file: chi phí cấp phát của class so với struct, cái giá thật của boxing, và khác biệt giữa struct có `IEquatable<T>` với struct không có khi làm key `Dictionary`. Chạy bằng `dotnet run`, hoặc dán thân `Main` vào `Start()` của một MonoBehaviour rồi đổi `Console.WriteLine` thành `Debug.Log`.

**Script**

```csharp
// Program.cs — .NET 6+ (dotnet new console && dotnet run)
// Trong Unity: copy thân Main vào Start(), đổi Console.WriteLine -> Debug.Log.
using System;
using System.Collections.Generic;
using System.Diagnostics;

class EnemyClass { public int Hp; public float X, Y, Z; }
struct EnemyStruct { public int Hp; public float X, Y, Z; }

// Key KHÔNG có IEquatable: Dictionary phải đi đường ValueType.Equals
struct SlowKey { public int X, Y; public object Tag; }

// Key CÓ IEquatable: Dictionary dùng comparer generic, không boxing
readonly struct FastKey : IEquatable<FastKey>
{
    public readonly int X, Y;
    public FastKey(int x, int y) { X = x; Y = y; }
    public bool Equals(FastKey o) => X == o.X && Y == o.Y;
    public override bool Equals(object o) => o is FastKey k && Equals(k);
    public override int GetHashCode() => X * 397 ^ Y;
}

interface IDamageable { int Hp { get; } }
struct Boxed : IDamageable { public int Hp { get; set; } }

static class Program
{
    const int N = 1_000_000;

    static void Main()
    {
        Console.WriteLine($"64-bit: {Environment.Is64BitProcess}\n");

        // 1) Cấp phát: 1 triệu class so với 1 triệu struct trong mảng
        long before = GC.GetTotalAllocatedBytes(true);
        var classes = new EnemyClass[N];
        for (int i = 0; i < N; i++) classes[i] = new EnemyClass { Hp = i };
        long classBytes = GC.GetTotalAllocatedBytes(true) - before;

        before = GC.GetTotalAllocatedBytes(true);
        var structs = new EnemyStruct[N];
        for (int i = 0; i < N; i++) structs[i] = new EnemyStruct { Hp = i };
        long structBytes = GC.GetTotalAllocatedBytes(true) - before;

        Console.WriteLine($"1M class : {classBytes / 1024 / 1024} MB  (mảng con trỏ + N object)");
        Console.WriteLine($"1M struct: {structBytes / 1024 / 1024} MB  (một mảng liền, 0 object)\n");

        // 2) Boxing: cùng một struct, một đường qua interface, một đường generic
        before = GC.GetTotalAllocatedBytes(true);
        int sum = 0;
        for (int i = 0; i < N; i++) { IDamageable d = new Boxed { Hp = i }; sum += d.Hp; }
        long boxBytes = GC.GetTotalAllocatedBytes(true) - before;

        before = GC.GetTotalAllocatedBytes(true);
        for (int i = 0; i < N; i++) sum += TakeGeneric(new Boxed { Hp = i });
        long genericBytes = GC.GetTotalAllocatedBytes(true) - before;

        Console.WriteLine($"1M lần ép sang interface: {boxBytes / 1024 / 1024} MB  <- boxing");
        Console.WriteLine($"1M lần qua generic      : {genericBytes} B   <- 0\n");

        // 3) Dictionary: key có và không có IEquatable
        Console.WriteLine($"Dictionary 200k lần tra, key KHÔNG IEquatable: {TimeSlowKey()} ms");
        Console.WriteLine($"Dictionary 200k lần tra, key CÓ    IEquatable: {TimeFastKey()} ms");
        Console.WriteLine($"(giữ sum để trình biên dịch không cắt vòng lặp: {sum})");
    }

    static int TakeGeneric<T>(T x) where T : IDamageable => x.Hp;   // không boxing

    static long TimeSlowKey()
    {
        var map = new Dictionary<SlowKey, int>();
        for (int i = 0; i < 1000; i++) map[new SlowKey { X = i, Y = i, Tag = null }] = i;
        var sw = Stopwatch.StartNew();
        int hit = 0;
        for (int i = 0; i < 200_000; i++)
            if (map.TryGetValue(new SlowKey { X = i % 1000, Y = i % 1000, Tag = null }, out _)) hit++;
        sw.Stop();
        return sw.ElapsedMilliseconds;
    }

    static long TimeFastKey()
    {
        var map = new Dictionary<FastKey, int>();
        for (int i = 0; i < 1000; i++) map[new FastKey(i, i)] = i;
        var sw = Stopwatch.StartNew();
        int hit = 0;
        for (int i = 0; i < 200_000; i++)
            if (map.TryGetValue(new FastKey(i % 1000, i % 1000), out _)) hit++;
        sw.Stop();
        return sw.ElapsedMilliseconds;
    }
}
```

**Chạy thử**
- Phần 1: mảng class tốn cỡ **32–40 MB** (8 byte con trỏ + ~32 byte mỗi object), mảng struct cỡ **15 MB** (16 byte × 1M, một khối liền). Tỉ lệ quan trọng hơn con số tuyệt đối.
- Phần 2: đường interface cấp phát **~24 MB**, đường generic in ra **0 B**. Đây là chỗ nhìn thấy boxing bằng số.
- Phần 3: key không có `IEquatable` chậm hơn **cỡ 5–20 lần** tuỳ runtime. Bỏ field `Tag` đi rồi chạy lại: khoảng cách thu hẹp — đó là bằng chứng rằng field kiểu tham chiếu mới là thứ đẩy `ValueType.Equals` vào đường reflection.
